function paperContent(){if(md!==initialMd)return markdown(md);return `<div class="eyebrow">Learning · 01</div><h1>客户沟通基础课</h1><p class="doc-sub">让每一次沟通，都从理解开始。</p><div class="doc-meta"><span>面向新员工</span><span>课程讲稿</span><span>约 5 分钟</span></div><h2>课程目标</h2><p>帮助新员工在真实工作场景中理解客户需求，用清晰、尊重的表达建立信任。</p><h2>第一节：先听懂，再回应</h2><div class="lesson-row"><div class="lesson-number">01</div><div>留出表达空间<span>不急于给出方案，让客户完整表达。</span></div></div><div class="lesson-row"><div class="lesson-number">02</div><div>确认真实需求<span>通过开放式提问，识别真正的关注点。</span></div></div><div class="lesson-row"><div class="lesson-number">03</div><div>给出清晰回应<span>用自己的话复述，并与客户确认。</span></div></div><blockquote>客户说“我再想想”，先理解顾虑，<br>再一起寻找下一步。</blockquote><h2>练习：一次更好的回应</h2><p>客户：“资料太多，我不知道从哪看起。”</p><p style="margin-top:10px">建议：“我们先从您最关心的问题开始。您现在更想了解使用方式，还是需要先比较不同选择？”</p><h2>本节检查点</h2><p>确认真实问题 · 避免超出资料的承诺 · 给出下一步</p>`}
function markdown(text){return esc(text).split('\n').map(l=>l.startsWith('# ')?`<h1>${l.slice(2)}</h1>`:l.startsWith('## ')?`<h2>${l.slice(3)}</h2>`:l.startsWith('&gt; ')?`<blockquote>${l.slice(5)}</blockquote>`:l.startsWith('- ')?`<p>• ${l.slice(2)}</p>`:l?`<p>${l}</p>`:'<br>').join('')}
