function workspace(){return `<div class="workspace">${sessionPanel()}${style==='b'?`<div class="studio-canvas">${documentPane()}${shelf()}</div>${chat()}`:`${chat()}${documentPane()}`}</div>`}
function libraryNav(){return `<aside class="library-nav"><h2>项目资源</h2><div class="section-label" style="margin-bottom:15px">资源分类</div>${[['全部资源','folder',7],['课程文档','doc',2],['图片素材','image',2],['视频素材','video',2],['音频素材','audio',1]].map(([n,i,c],k)=>`<button class="folder ${k===0?'active':''}" onclick="folderFilter('${['全部','文档','图片','视频','音频'][k]}',this)">${icon(i)}${n}<span>${c}</span></button>`).join('')}<div class="section-divider"></div><div class="section-label" style="margin:22px 0 10px">集合</div><button class="folder" onclick="setFilter('全部');toast('已显示客户沟通课程的全部资源')">${icon('layers')}客户沟通课程</button></aside>`}
function resourceRows(){let list=resources.filter(r=>(filter==='全部'||r.type===filter)&&r.name.toLowerCase().includes((document.querySelector('#resourceSearch')?.value||'').toLowerCase()));if(!list.length)return '<div class="empty">没有找到匹配的资源<br><button class="quiet" onclick="resetResources()">清除筛选</button></div>';if(style==='b')return `<div class="resource-grid">${list.map(r=>`<button class="resource-card ${r.id===selectedId?'selected':''}" onclick="selectResource(${r.id})"><span class="check">${r.id===selectedId?icon('check'):''}</span>${art(r)}<div class="resource-caption"><div><strong>${r.name}</strong><small>${r.type} · ${r.size}</small></div><small>${r.date}</small></div></button>`).join('')}</div>`;return `<table class="resource-table"><thead><tr><th style="width:30px"></th><th>资源名称</th><th>类型</th><th>大小</th><th>更新日期</th></tr></thead><tbody>${list.map(r=>`<tr class="${r.id===selectedId?'selected':''}" onclick="selectResource(${r.id})" tabindex="0" onkeydown="if(event.key==='Enter')selectResource(${r.id})"><td><input type="radio" name="resource" ${r.id===selectedId?'checked':''} aria-label="选择${r.name}" tabindex="-1"></td><td><div class="row"><span class="fileicon">${icon(r.kind)}</span><strong>${r.name}</strong></div></td><td>${r.type}</td><td class="muted">${r.size}</td><td class="muted">${r.date}</td></tr>`).join('')}</tbody></table>`}
function resourceDetail(){let r=resources.find(r=>r.id===selectedId);return `<div class="row between"><strong style="font-size:13px">资源详情</strong><span class="pill">${r.type}</span></div>${art(r)}<h2>${r.name}</h2><p class="tiny" style="line-height:1.9">${r.note}</p><div><div class="detail-pair"><span>所属项目</span><span>新员工课程共创</span></div><div class="detail-pair"><span>文件大小</span><span>${r.size}</span></div><div class="detail-pair"><span>更新时间</span><span>2026年${r.date}</span></div><div class="detail-pair"><span>可见范围</span><span>本项目成员</span></div></div><button onclick="previewResource(${r.id})">${icon('external')}预览资源</button><div class="notice" style="margin-top:auto">在内容协作中，通过输入区“参考”选择需要引用的资源。</div>`}
function library(){return `<div class="library-shell">${style!=='b'?libraryNav():''}<section class="library-content"><div class="row between library-heading"><h1>${style==='b'?'让好内容，有迹可循。':'全部资源'}</h1><button class="primary" onclick="uploadModal()">${icon('plus')}上传资源</button></div><div class="search-line"><div class="searchbox">${icon('search')}<input id="resourceSearch" placeholder="搜索项目资源" aria-label="搜索项目资源" oninput="updateResources()"></div><div class="filters">${['全部','文档','图片','视频','音频'].map(t=>`<button data-filter="${t}" class="${t===filter?'active':''}" onclick="setFilter('${t}')">${t}</button>`).join('')}</div></div><div class="row between" style="margin-bottom:18px"><span class="tiny">客户沟通课程 · ${resources.length} 份素材</span><span class="tiny">最近更新</span></div><div id="resourceResults">${resourceRows()}</div>${style==='b'?'<div class="notice" style="margin-top:24px">先选素材，再开始共创。原始文件保留在项目资源库中。</div>':''}</section><aside class="resource-detail" id="resourceDetail">${resourceDetail()}</aside></div>`}
const skills=[['微课结构检查','全局 · 只读','检查学习目标、内容结构与练习闭环'],['口语化讲稿','本项目','把书面表达转换为自然、易理解的口播'],['来源与事实核验','全局 · 只读','区分资料事实、推断与待确认信息']];
function skillsList(){return skills.map(([n,t,d],i)=>`<div class="skill-row"><span class="fileicon">${icon(t.includes('全局')?'lock':'layers')}</span><div><strong>${n}</strong><small>${d}</small></div><span class="pill">${t}</span></div>`).join('')+(read('skill',null)?`<div class="skill-row">${icon('check')}<div><strong>${esc(read('skill',{}).name)}</strong><small>来自会话 · 已确认保存</small></div><span class="pill">本项目</span></div>`:'')}
function agentSide(){return `<aside class="agent-sidebar"><h2>智能体配置</h2><div class="section-label" style="margin:0 12px 12px">项目智能体</div><button class="agent-list-item active" onclick="configTab('skills')"><span class="fileicon">${icon('spark')}</span><div><strong>内容协作智能体</strong><small>技能 · 参考资料 · 调试</small></div></button><div class="section-divider"></div><button class="folder" onclick="configTab('skills')">${icon('layers')}技能</button><button class="folder" onclick="configTab('references')">${icon('folder')}参考资料</button><button class="folder" onclick="configTab('prompt')">${icon('doc')}提示词</button><div class="notice" style="margin-top:36px">全局技能由授权维护者统一维护。项目成员可选择使用，或提出更新申请。</div></aside>`}
function configForm(){return `<div class="row between config-title"><div><h1>内容协作智能体</h1></div><button class="primary" onclick="saveConfig()">保存配置</button></div><div class="config-tabs"><button data-tab="skills" class="active" onclick="configTab('skills')">技能管理</button><button data-tab="references" onclick="configTab('references')">参考资料</button><button data-tab="prompt" onclick="configTab('prompt')">提示词管理</button></div><div id="configTabContent">${configSkills()}</div>`}
function configSkills(){return `<div class="config-grid"><div><div class="form-field"><label for="agentName">智能体名称</label><input id="agentName" value="${esc(read('config',{}).name||'内容协作智能体')}"></div><div class="form-field"><label for="agentInstruction">角色与协作方式</label><textarea id="agentInstruction">${esc(read('config',{}).instruction||'你是新员工课程的内容共创伙伴。\n基于项目资料组织教学内容；事实不充分时先提出待确认问题。\n优先输出 Markdown 讲稿，由用户确认后继续。')}</textarea><small>说明应如何协作，以及哪些决定需要人工确认。</small></div></div><div><div class="row between" style="margin-bottom:7px"><label style="margin:0">可用技能</label><button class="quiet tiny" onclick="skillInfo()">查看权限</button></div>${skillsList()}<button class="quiet" style="font-size:11px;margin-top:12px" onclick="skillModal()">${icon('plus')}从会话沉淀项目技能</button></div></div><div class="notice" style="margin-top:22px">全局技能仅可引用；修改已有技能需提交更新申请。配置保存后对项目生效。</div>`}
function testPane(){return `<aside class="test-panel"><div class="panel-head"><strong style="font-size:14px">预览与调试</strong><span class="pill">预览</span></div><div class="chat-scroll"><div class="tiny" style="margin-bottom:15px">测试输入</div><div class="human" style="margin-left:0">请根据培训手册，检查客户沟通基础课的结构。</div><div class="ai-name">${icon('spark')}<span>执行过程</span></div><div class="test-steps"><div class="test-step">${icon('check')}读取项目参考资料<span class="spacer"></span><span class="tiny">2 份</span></div><div class="test-step">${icon('check')}匹配微课结构检查<span class="spacer"></span><span class="tiny">v1.2</span></div><div class="test-step">${icon('check')}形成检查建议<span class="spacer"></span><span class="tiny">已完成</span></div></div><div class="test-output" id="testOutput"><strong>结构清晰，可继续完善练习。</strong><p style="margin-top:11px">已有明确目标和三个内容层次。建议给练习增加“如何判断回应有效”的检查点，便于新员工自查。</p><div class="small-kpi"><span>参考资料 2 份</span><span>调用技能 1 项</span></div></div></div><div class="composer-wrap"><textarea id="testInput" style="width:100%;height:74px;font-size:12px" placeholder="输入一条测试问题" aria-label="测试问题"></textarea><button class="primary" style="margin-top:10px;width:100%" onclick="runTest()">运行测试</button><p class="tiny" style="font-size:9px;margin-top:8px;text-align:center">测试结果需人工确认</p></div></aside>`}
function agents(){if(style==='b')return `<div class="studio-config"><div class="studio-config-top"><h1>为你的创作，配好工具。</h1><span class="pill">新员工课程共创</span></div><div class="studio-agent-cards"><button class="studio-agent-card selected" onclick="configTab('skills')"><div class="agent-symbol">${icon('spark')}</div><div><h3>内容协作智能体</h3><p>理解资料，生成可编辑的课程内容。</p></div><span class="pill" style="margin-top:14px">当前配置</span></button><button class="studio-agent-card" onclick="configTab('references')"><div class="agent-symbol">${icon('folder')}</div><div><h3>项目参考资料</h3><p>把创作所需的文档、图片和视频放在一起。</p></div><span class="tiny" style="display:block;margin-top:14px">2 份参考已选</span></button><button class="studio-agent-card" onclick="skillModal()"><div class="agent-symbol">${icon('layers')}</div><div><h3>共创经验</h3><p>将验证有效的协作方法，沉淀为项目技能。</p></div><span class="tiny" style="display:block;margin-top:14px">总结后由你确认保存</span></button></div><div class="studio-config-bottom"><section class="config-main">${configForm()}</section>${testPane()}</div></div>`;return `<div class="config-shell">${agentSide()}<section class="config-main">${configForm()}</section>${testPane()}</div>`}
 function viewSavedSkill(){const saved=read('skill',null);if(saved)openModal('技能正文',`<pre class="studio-skill-body">${esc(saved.body)}</pre>`)}
 function skillManagement(){const saved=read('skill',null);return `<main class="studio-skills"><div class="studio-skills-heading"><div><span class="studio-skills-kicker">项目技能</span><h1>技能管理</h1><p>查看项目可用技能，复用经过确认的内容创作方法。</p></div><button class="primary" onclick="location.href=url('workspace')">${icon('plus')}前往会话创建技能</button></div><div class="studio-skills-list">${skills.map(([name,type,desc])=>`<article class="studio-skill-card"><span class="studio-skill-icon">${icon('layers')}</span><div><strong>${esc(name)}</strong><p>${esc(desc)}</p><small>${esc(type)}</small></div><span class="pill">可用</span></article>`).join('')}${saved?`<article class="studio-skill-card"><span class="studio-skill-icon">${icon('layers')}</span><div><strong>${esc(saved.name)}</strong><p>从内容协作会话总结并确认保存</p><small>本项目</small></div><button class="quiet" onclick="viewSavedSkill()">查看</button></article>`:''}</div></main>`}
function originalModule(){const prompt=qs.get('tab')==='prompt';let src=page==='resources'?'../PG07-资源管理/资源管理原型.html?embed=ai':'../PG13-智能体配置/智能体配置原型.html?embed=ai&tab='+(prompt?'prompt':'skill');if(qs.has('project'))src+='&project='+encodeURIComponent(qs.get('project'));return `<section class="studio-original-module">${page==='skills'?`<nav class="studio-skill-subnav" aria-label="技能管理页面"><a href="${url('skills')}&tab=skill" class="${prompt?'':'active'}" ${prompt?'':'aria-current="page"'}>技能管理</a><a href="${url('skills')}&tab=prompt" class="${prompt?'active':''}" ${prompt?'aria-current="page"':''}>提示词管理</a></nav>`:''}<iframe class="studio-original-frame" title="${page==='resources'?'资源管理':prompt?'提示词管理':'技能管理'}" src="${src}"></iframe></section>`}
 document.body.className='style-'+style;document.title=`${names[style]} · ${navItems.find(n=>n[0]===page)[2]} · AI协作`;document.querySelector('#app').innerHTML=shell(page==='workspace'?workspace():style==='b'&&['resources','skills'].includes(page)?originalModule():page==='resources'?library():agents());
let composing=false;document.querySelector('#message')?.addEventListener('compositionstart',()=>composing=true);document.querySelector('#message')?.addEventListener('compositionend',()=>composing=false);document.querySelector('#message')?.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&!composing&&e.keyCode!==229){e.preventDefault();sendMessage()}});
document.querySelectorAll('a[href]').forEach(a=>a.addEventListener('click',e=>{if(dirty){e.preventDefault();leaveModal(a.href)}}));
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
let toastTimer;function toast(s){if(style==='b')return beautifulToast(s);const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3600)}
function openModal(title,body,actions=''){if(style==='b')return beautifulModal(title,body,actions);const m=document.querySelector('#modal');m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="quiet" aria-label="关闭" onclick="closeModal()">${icon('x')}</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}`;m.showModal()}
function closeModal(){document.querySelector('#modal').close()}
function focusDoc(){if(document.querySelector('#paper')?.dataset.asset){document.querySelector('#paper').removeAttribute('data-asset');document.querySelector('#paper').innerHTML=paperContent();document.querySelector('.doc-name strong').textContent='客户沟通基础课.md';document.querySelector('#editButton').disabled=false;document.querySelector('#editButton').hidden=false;document.querySelector('#editButton').innerHTML=icon('edit')+'编辑';document.querySelector('.bui-file-tile').innerHTML=icon('doc');document.querySelector('#regionButton')?.setAttribute('hidden','');document.querySelector('#quoteButton').disabled=false;if(document.querySelector('#saveVersionButton'))document.querySelector('#saveVersionButton').disabled=false;document.querySelector('#archiveButton').disabled=false;document.querySelector('#saveStatus').textContent='已保存';document.querySelectorAll('.output-thumb').forEach((x,i)=>x.classList.toggle('active',i===0));}document.querySelector('#documentPane')?.scrollIntoView({behavior:'smooth',block:'nearest'});toast('已打开 Markdown 成果')}
function toggleEdit(){if(editing){md=document.querySelector('#markdownEditor').value;document.querySelector('#paper').innerHTML=paperContent();document.querySelector('#editButton').textContent='编辑'}else{document.querySelector('#paper').innerHTML=`<textarea class="md-editor" id="markdownEditor" aria-label="Markdown 源码">${esc(md)}</textarea>`;document.querySelector('#markdownEditor').addEventListener('input',()=>{dirty=true;document.querySelector('#saveStatus').textContent='未保存 · 本地草稿'});document.querySelector('#editButton').textContent='预览'}editing=!editing}
function saveDocument(){if(document.querySelector('#paper')?.dataset.asset){toast('当前素材为只读，请切换 Markdown 讲稿后保存');return false}if(editing)md=document.querySelector('#markdownEditor').value;if(!md.trim()){toast('文档内容不能为空，草稿已保留');return false}if(dirty)version++;write('markdown',md);write('version',version);dirty=false;document.querySelector('#versionLabel').textContent='v'+version;document.querySelector('#saveStatus').textContent='已保存 · 当前版本';toast(`v${version} 已保存到此浏览器`);return true}
function archiveDoc(){if(document.querySelector('#paper')?.dataset.asset)return toast('当前为已保存，未保存到真实资源库');if(dirty)return toast('请先保存当前版本，再存入资源库');toast(`已将客户沟通基础课 v${version} 保存到本项目资源库，未上传服务器`)}
function leaveModal(href){openModal('有尚未保存的修改','<p>保存当前 Markdown 草稿后再离开，或放弃本次修改。</p>',`<button onclick="closeModal()">继续编辑</button><button onclick="dirty=false;location.href='${esc(href)}'">放弃修改</button><button class="primary" onclick="if(saveDocument()){dirty=false;location.href='${esc(href)}'}">保存并离开</button>`)}
function sendPreset(t){document.querySelector('#message').value=t;sendMessage()}
function sendMessage(){let input=document.querySelector('#message'),s=input.value.trim();if(!s)return toast('请先输入协作需求');input.value='';let log=document.querySelector('#chatLog');log.insertAdjacentHTML('beforeend',`<div class="human" style="margin-top:23px">${esc(s)}</div>`);if(/经验|沉淀|总结.*技能/.test(s)){log.insertAdjacentHTML('beforeend',`<div class="ai-name">${icon('spark')}技能候选</div><p class="ai-copy">已准备会话经验草稿，请检查内容后确认保存到本项目。</p><button class="result-card" onclick="skillModal()">${icon('layers')}查看并确认技能草稿</button>`);skillModal()}else{log.insertAdjacentHTML('beforeend',`<div class="ai-name">${icon('spark')}内容协作智能体</div><p class="ai-copy">已收到“${esc(s)}”。可以继续编辑画布中的讲稿，或查看已引用的资源。</p><span class="pill">处理反馈</span>`)}log.scrollTop=log.scrollHeight}
function skillModal(){openModal('将这次经验沉淀为项目技能',`<span class="pill">来源：客户沟通基础课 · 当前会话</span><label for="skillName">技能名称</label><input id="skillName" value="客户沟通微课共创方法"><label for="skillBody">技能正文 · Markdown</label><textarea id="skillBody"># 客户沟通微课共创方法\n\n## 适用场景\n依据项目培训资料，为新员工整理沟通微课。\n\n## 输入\n培训手册、目标学员与具体沟通场景。\n\n## 步骤\n1. 提取资料中的目标与边界。\n2. 将内容收敛为三个可练习的动作。\n3. 配置真实场景与示范回应。\n4. 由人工确认事实、表达和检查点。\n\n## 输出与限制\n输出 Markdown 讲稿；不补造承诺、条款或客户信息。</textarea><div class="notice" style="margin-top:15px">保存后，本项目成员可查看并使用技能正文；来源会话仍按原权限访问。</div>`,`<button onclick="closeModal()">暂不保存</button><button class="primary" onclick="saveSkill()">确认保存到本项目</button>`)}
function saveSkill(){let n=document.querySelector('#skillName').value.trim(),body=document.querySelector('#skillBody').value.trim();if(!n||!body)return toast('请填写技能名称与正文');write('skill',{name:n,body});closeModal();toast(style==='b'?'项目技能已保存':'项目技能已保存，可在智能体配置中查看');if(page==='agents')configTab('skills')}
function openReferences(){openModal('选择项目参考资料',`<div class="stack">${resources.map(r=>`<button class="row between" style="text-align:left" onclick="referenceResource(${r.id},true)"><span>${icon(r.kind)} ${r.name}</span><span class="tiny">${r.type}</span></button>`).join('')}</div><p class="tiny" style="margin-top:18px">仅显示当前项目可访问资源，引用不会修改原文件。</p>`)}
function referenceResource(id,stay=false){let r=resources.find(r=>r.id===id);write('reference',r.name);if(stay){closeModal();document.querySelector('#referenceSelected')&&(document.querySelector('#referenceSelected').textContent='引用：'+r.name);toast('资源已加入当前会话')}else{location.href=url('workspace')}}
function selectSkills(){openModal('选择本次协作技能',skills.map(([n,t,d])=>`<div class="skill-row"><input type="checkbox" checked aria-label="选择使用${n}"><div><strong>${n}</strong><small>${d}</small></div><span class="pill">${t}</span></div>`).join('')+'<div class="notice" style="margin-top:20px">全局技能只读；已选技能随本次消息引用。</div>',`<button class="primary" onclick="closeModal();toast('本次技能选择已确认')">确认选择</button>`)}
function previewResource(id){let r=resources.find(r=>r.id===id);openModal(r.name,`${art(r)}<p style="margin-top:20px;font-size:13px;line-height:1.9">${r.kind==='doc'?'培训内容重点：留出表达空间，确认真实需求，并给出清晰回应。':r.note}</p><div class="notice" style="margin-top:15px">${r.kind==='video'?'视频预览':''}</div>`,`<button onclick="closeModal()">关闭</button>${page==='workspace'?`<button class="primary" onclick="referenceResource(${id},true)">引用到会话</button>`:''}`)}
function selectResource(id){selectedId=id;updateResources();document.querySelector('#resourceDetail').innerHTML=resourceDetail()}
function updateResources(){document.querySelector('#resourceResults').innerHTML=resourceRows()}
function setFilter(t){filter=t;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===t));updateResources()}
function folderFilter(t,button){document.querySelectorAll('.folder').forEach(b=>b.classList.remove('active'));button.classList.add('active');setFilter(t)}
function resetResources(){document.querySelector('#resourceSearch').value='';setFilter('全部')}
function uploadModal(){openModal('上传项目资源','<p class="tiny">选择本地文档、图片或视频，请确认文件后上传。</p><input type="file" id="localFile" style="margin-top:20px" aria-label="选择上传文件">',`<button onclick="closeModal()">取消</button><button class="primary" onclick="uploadFeedback()">确认上传</button>`)}
function uploadFeedback(){let f=document.querySelector('#localFile').files[0];if(!f)return toast('请先选择一个文件');closeModal();toast(`已选择 ${f.name}。文件已加入上传队列`)}
function configTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let el=document.querySelector('#configTabContent');if(tab==='skills')el.innerHTML=configSkills();else if(tab==='references')el.innerHTML=`<h3 style="margin-bottom:18px">项目参考资料</h3>${resources.map((r,i)=>`<div class="skill-row"><input type="checkbox" ${i<2?'checked':''} aria-label="使用${r.name}"><span class="fileicon">${icon(r.kind)}</span><div><strong>${r.name}</strong><small>${r.type} · ${r.size}</small></div></div>`).join('')}<div class="notice" style="margin-top:20px">仅选择本项目可访问的参考资料。保存配置不会修改原资源。</div>`;else el.innerHTML=promptList()}
function saveConfig(){if(document.querySelector('#agentName')){let n=document.querySelector('#agentName').value.trim();if(!n)return toast('智能体名称不能为空');write('config',{name:n,instruction:document.querySelector('#agentInstruction').value})}if(document.querySelector('#systemPrompt'))write('prompt',document.querySelector('#systemPrompt').value);toast('配置草稿已保存到此浏览器，未修改全局技能')}
function runTest(){let input=document.querySelector('#testInput').value.trim();if(!input)return toast('请输入一条测试问题');document.querySelector('#testOutput').innerHTML=`<span class="pill">处理反馈 · 未调用 AI</span><p style="margin-top:12px">测试问题：${esc(input)}</p><p style="margin-top:12px">已使用当前技能与参考资料。</p>`;toast('测试完成')}
function skillInfo(){openModal('技能使用与维护权限','<p style="line-height:1.9;font-size:13px">项目成员可使用启用的全局技能与本项目技能。全局技能由授权维护者统一管理。<br><br>你可以在会话中总结经验，确认后保存为本项目的新技能；修改已有技能时，需提交更新申请。</p>',`<button class="primary" onclick="closeModal()">知道了</button>`)}
function newSession(){openModal('新建关联会话','<p class="tiny">项目：新员工课程共创 · 任务：客户沟通基础课</p><label for="sessionName">会话名称</label><input id="sessionName" placeholder="例如：优化课程开场">',`<button onclick="closeModal()">取消</button><button class="primary" onclick="createSession()">开始共创</button>`)}
function createSession(){let name=document.querySelector('#sessionName').value.trim();if(!name)return toast('请填写会话名称');closeModal();toast(`已创建会话“${name}”，项目与任务上下文保持不变`)}
function showSession(n){openModal(n,'<p style="line-height:1.9">查看当前任务的历史会话。</p>',`<button class="primary" onclick="closeModal()">返回当前会话</button>`)}

function taskModal(){openModal("客户沟通基础课",`<span class="pill">创作中</span><div class="detail-pair"><span>所属项目</span><span>新员工课程共创</span></div><div class="detail-pair"><span>负责人</span><span>林悦</span></div><div class="section-divider"></div><p style="font-size:13px;line-height:1.9">为新员工整理客户沟通基础课。内容应基于项目培训手册，包含课程目标、练习情境和检查点；不补充未经确认的承诺。</p><div class="notice" style="margin-top:18px">查看关联任务摘要。</div>`,`<button class="primary" onclick="closeModal()">继续创作</button>`)}

const promptTypes=['主约束','场景识别','参数抽取','技能路由','结果表达','人工确认'];
function promptList(){return `<div class="row between" style="margin-bottom:16px"><h3>提示词管理</h3><span class="tiny">本项目 · 六类提示词</span></div>${promptTypes.map((t,i)=>`<button class="skill-row" style="width:100%;text-align:left;white-space:normal;border:0;border-bottom:1px solid var(--line);border-radius:0;background:none" onclick="promptDetail(${i})"><span class="fileicon">${icon('doc')}</span><div><strong>${t==='主约束'?'课程内容共创约束':t+'规则'}</strong><small>${t} · v1.0 · 已发布</small></div><span class="spacer"></span>${icon('chevron')}</button>`).join('')}<div class="notice" style="margin-top:20px">类别用于组织提示词，不代表固定执行顺序。</div>`}
function promptDetail(i){let t=promptTypes[i];openModal('提示词详情',`<label>名称</label><input id="promptName" value="${t==='主约束'?'课程内容共创约束':t+'规则'}" readonly><label>类型</label><input value="${t}" readonly><label>正文</label><textarea readonly>${t==='人工确认'?'在保存共享技能、提交成果前，展示内容及影响范围，由用户明确确认。':'根据项目参考资料协助整理课程内容。事实不充分时明确待确认项，保留人工决策，不补造业务事实。'}</textarea><div class="row between" style="margin-top:14px"><span class="tiny">v1.0 · 已发布 · 本项目</span><span class="pill">只读预览</span></div>`,`<button class="primary" onclick="closeModal()">关闭</button>`)}
function outputPicker(){openModal('本次会话成果',`<div class="stack"><button class="row" onclick="closeModal();focusDoc()">${icon('doc')}客户沟通基础课.md <span class="tiny">v${version}</span></button><button class="row" onclick="closeModal();showAsset('image')">${icon('image')}课程开场配图 <span class="tiny">图片</span></button><button class="row" onclick="closeModal();showAsset('video')">${icon('video')}沟通情境片段 <span class="tiny">视频</span></button></div>`)}
function showAsset(kind){if(dirty){toast('请先保存 Markdown 草稿，再切换成果');return}editing=false;let r=resources[kind==='video'?2:1],p=document.querySelector('#paper');p.dataset.asset=kind;p.innerHTML=`<div class="eyebrow">${kind==='video'?'VIDEO':'IMAGE'} · 课程成果</div><h1>${kind==='video'?'沟通情境片段':'课程开场配图'}</h1><p class="doc-sub">客户沟通基础课 · 学习情境</p><div class="large-art">${art(r)}</div><div class="row between" style="margin-top:24px"><span class="pill">${kind==='video'?'视频封面':'场景插画'}</span><span class="tiny">${kind==='video'?'16:9 · 00:48':'16:9 · 情境导入'}</span></div><h2>先理解，再回应</h2><p>以平等的对话姿态，呈现新员工倾听客户与确认需求的课程情境。</p><div class="row" style="margin-top:24px"><button onclick="assetQuestion()">围绕此内容提问</button><button onclick="focusDoc()">返回课程讲稿</button></div>`;document.querySelector('.doc-name strong').textContent=kind==='video'?'沟通情境片段.mp4':'课程开场配图.png';document.querySelector('#editButton').disabled=true;document.querySelector('#saveVersionButton').disabled=true;document.querySelector('#archiveButton').disabled=true;document.querySelector('#editButton').textContent='编辑';document.querySelector('#saveStatus').textContent='素材已就绪';document.querySelectorAll('.output-thumb').forEach((x,i)=>x.classList.toggle('active',i===(kind==='video'?2:1)));}
function assetQuestion(){let m=document.querySelector('#message');m.value='请围绕这份课程素材，';m.focus();document.querySelector('#referenceSelected').textContent='引用：'+document.querySelector('.doc-name strong').textContent}
if(page==='workspace'&&style!=='b'&&['image','video'].includes(qs.get('asset')))showAsset(qs.get('asset'));

/* B iteration: session context and output filtering are scoped to this workspace. */
function studioSessionPanel(){return `<aside class="session-panel studio-session-panel"><div class="row between"><h2>会话记录</h2><button class="new-session-button quiet" id="newSessionButton" aria-label="新增会话" title="新增会话" onclick="newStudioSession()">${icon('plus')}</button></div><div class="session-search">${icon('search')}<input id="sessionSearch" aria-label="搜索会话记录" placeholder="搜索会话" oninput="searchStudioSessions(this.value)"><button class="bui-clear-search quiet" aria-label="清除会话搜索" onclick="clearSessionSearch()">${icon('x')}</button></div><div class="studio-session-list bui-glide" id="studioSessionList" onpointermove="glideSessionHighlight(event)" onpointerleave="clearSessionHighlight()" onfocusin="glideSessionHighlight(event)" onfocusout="if(!this.contains(event.relatedTarget))clearSessionHighlight()">${studioSessionRows()}</div></aside>`}
function studioSessionRows(query=''){const sessions=studioSessions.filter(t=>t.name.includes(query));return sessions.length?sessions.map(t=>`<button class="studio-session ${t.id===studioSessionId?'active':''}" data-session-id="${t.id}" aria-current="${t.id===studioSessionId?'true':'false'}" onclick="selectStudioSession('${t.id}')"><span class="session-name" title="${esc(t.name)}">${esc(t.name)}</span>${t.status?`<span class="session-status ${t.status==='进行中'?'running':'done'}" title="${t.status} · AI 执行状态" role="img" aria-label="${t.status}">${icon(t.status==='进行中'?'clock':'check')}</span>`:''}</button>`).join(''):'<div class="session-search-empty">没有匹配的会话</div>'}

function searchStudioSessions(q){document.querySelector('#studioSessionList').innerHTML=studioSessionRows(q);document.querySelector('.session-search').classList.toggle('has-query',!!q);clearSessionHighlight()}
function studioOutputItems(){const outputNames={doc:'客户沟通基础课.md',image:'课程开场配图',audio:'沟通练习示范音频',video:'沟通情境片段'},outputLabels={doc:'文稿',image:'图片',audio:'音频',video:'视频'},outputResources={image:1,audio:6,video:2};if(!currentStudioSession().hasOutputs)return `<div class="output-empty">${icon(studioOutputFilter||'layers')}<span>暂无${outputLabels[studioOutputFilter]||''}成果</span></div>`;return ['doc','image','audio','video'].filter(t=>!studioOutputFilter||studioOutputFilter===t).map(type=>`<button class="output-thumb output-${type} ${studioSelectedOutput===type?'active':''}" data-output-type="${type}" aria-pressed="${studioSelectedOutput===type}" aria-label="${outputNames[type]}" title="${outputNames[type]} · ${outputLabels[type]}" onclick="selectStudioOutput('${type}')">${type==='doc'?`${icon('doc')}<span class="output-document-name">${outputNames.doc}</span>`:art(resources[outputResources[type]])}</button>`).join('')}
function refreshStudioShelf(){const shelfEl=document.querySelector('#outputShelf');if(shelfEl)shelfEl.outerHTML=shelf()}
function filterStudioOutputs(type){studioOutputFilter=studioOutputFilter===type?null:type;refreshStudioShelf()}
function selectStudioOutput(type){if(!currentStudioSession().hasOutputs)return;if(type==='doc')focusDoc();else showAsset(type)}
function captureStudioSession(){if(editing&&document.querySelector('#markdownEditor'))md=document.querySelector('#markdownEditor').value;studioSessionSnapshots[studioSessionId]={md,version,editing,dirty,asset:document.querySelector('#paper')?.dataset.asset||null,message:document.querySelector('#message').value,chat:document.querySelector('#chatLog').innerHTML,resourceRefs:[...studioResourceRefs],filter:studioOutputFilter,selected:studioSelectedOutput,model:selectedModel,localAttachments:[...localAttachments]}}
function selectStudioSession(id){if(id===studioSessionId)return;if(!studioSessions.some(t=>t.id===id))return;if(dirty){openModal('保存当前会话的修改？',`<p>“${esc(currentStudioSession().name)}”有尚未保存的 Markdown 修改。处理后再切换会话。</p>`,`<button onclick="closeModal()">继续编辑</button><button onclick="discardStudioChanges();closeModal();switchStudioSession('${id}')">放弃修改</button><button class="primary" onclick="if(saveDocument()){closeModal();switchStudioSession('${id}')}">保存并切换</button>`);return}switchStudioSession(id)}
function discardStudioChanges(){md=read('markdown',initialMd);version=read('version',2);dirty=false;editing=false}
function switchStudioSession(id){captureStudioSession();canvasCitation=null;document.querySelector('#canvasCitationDraft')?.remove();studioSessionId=id;const session=currentStudioSession(),snap=studioSessionSnapshots[id];selectedModel=snap?.model||'qwen3.7-plus';localAttachments=[...(snap?.localAttachments||[])];studioResourceRefs=[...(snap?.resourceRefs||[])];modelBusy=(activeModelRuns.get(id)||0)>0;refreshModelPicker();renderLocalAttachments();md=snap?.md||'';version=snap?.version||1;dirty=false;editing=false;studioOutputFilter=snap?.filter||null;studioSelectedOutput=snap?.selected||'doc';document.querySelector('#studioSessionList').innerHTML=studioSessionRows(document.querySelector('#sessionSearch').value);document.querySelector('.studio-canvas').innerHTML=documentPane()+shelf();document.querySelector('#chatLog').innerHTML=snap?.chat||`<div class="session-chat-intro"><span class="session-intro-icon">${icon('spark')}</span><h3>${esc(session.name)}</h3><p>${esc(session.brief)}</p><span class="tiny">每次会话独立保留内容</span></div>`;document.querySelector('#message').value=snap?.message||'';renderStudioResourceRefs();document.querySelector('#message').placeholder=session.hasOutputs?'说说你想如何调整这份内容…':'描述你希望如何开始这次会话…';document.querySelector('.chat-panel .panel-head > .tiny').textContent=session.status||'';document.querySelector('#documentPane').dataset.sessionId=id;
 if(session.hasOutputs){md=snap?.md||read('markdown',initialMd);document.querySelector('#paper').innerHTML=paperContent();if(snap?.editing){toggleEdit()}if(snap?.asset)showAsset(snap.asset)}else{renderStudioEmpty(session)}
 const u=new URL(location.href);u.searchParams.set('session',id);u.searchParams.delete('task');u.searchParams.delete('asset');history.replaceState(null,'',u);document.querySelectorAll('a[href]').forEach(a=>{if(a.getAttribute('href').startsWith('index.html?')){const link=new URL(a.href);link.searchParams.set('session',id);link.searchParams.delete('task');a.href=link.href}});refreshStudioShelf();beautifySelectedReference();document.querySelector('#chatLog').scrollTop=0;
}
function renderStudioEmpty(session){document.querySelector('.doc-name strong').textContent=session.name;document.querySelector('#versionLabel').textContent='';document.querySelector('#paper').classList.add('empty-paper');document.querySelector('#paper').innerHTML=`<div class="session-empty-state"><span class="session-empty-icon">${icon('doc')}</span><h2>从一个想法开始</h2><p>“${esc(session.name)}”暂无可预览成果。<br>在右侧与智能体讨论目标，逐步形成内容。</p><button onclick="document.querySelector('#message').focus()">开始对话</button></div>`;for(const id of ['editButton','quoteButton','archiveButton'])document.querySelector('#'+id).disabled=true;document.querySelector('#regionButton').hidden=true;document.querySelector('#saveStatus').textContent='暂无成果'}
if(style==='b'&&page==='workspace'){
 openReferences=beautifulReferences;selectSkills=beautifulSkillSelector;
 const originalFocusDoc=focusDoc,originalShowAsset=showAsset,originalSaveDocument=saveDocument,originalToggleEdit=toggleEdit,originalArchiveDoc=archiveDoc,originalSendMessage=sendMessage,originalSkillModal=skillModal;
 focusDoc=function(){if(!currentStudioSession().hasOutputs)return toast('当前会话暂无文档成果');originalFocusDoc();studioSelectedOutput='doc';refreshStudioShelf()};
  showAsset=function(kind){if(!currentStudioSession().hasOutputs)return toast('当前会话暂无媒体成果');if(dirty)return toast('请先保存 Markdown 草稿，再切换成果');editing=false;const r=resources[kind==='video'?2:1],p=document.querySelector('#paper');p.dataset.asset=kind;p.innerHTML=`<div class="eyebrow">${kind==='video'?'VIDEO':'IMAGE'} · 课程成果</div><h1>${kind==='video'?'沟通情境片段':'课程开场配图'}</h1><p class="doc-sub">客户沟通基础课 · 学习情境</p><div class="large-art studio-media-art">${kind==='image'?`<div class="region-image" id="regionImage" role="img" aria-label="课程开场配图，可框选局部区域">${art(r)}<div class="region-marks" id="regionMarks"></div><div class="region-draft" id="regionDraft" hidden></div></div>`:art(r)}</div><div class="row between" style="margin-top:20px"><span class="pill">${kind==='video'?'视频封面':'场景插画'}</span><span class="tiny">${kind==='video'?'16:9 · 00:48':'拖动框选图片区域，可连续添加提问或备注'}</span></div>${kind==='image'?`<div class="region-note-panel" id="regionNotePanel" hidden><div class="region-note-head"><strong>局部区域 <span id="regionNumber"></span></strong><span id="regionCoordinates"></span></div><div class="region-note-types" role="group" aria-label="标注类型"><label><input type="radio" name="regionNoteType" value="提问" checked> 提问</label><label><input type="radio" name="regionNoteType" value="备注"> 备注</label></div><textarea id="regionNoteText" aria-label="局部提问或备注" placeholder="描述这个区域的问题或补充备注…"></textarea><div class="region-note-actions"><button class="quiet" onclick="cancelImageRegion()">取消</button><button class="primary" onclick="addImageRegionNote()">引用到会话</button></div></div><div class="region-note-list" id="regionNoteList"></div>`:''}`;document.querySelector('.doc-name strong').textContent=kind==='video'?'沟通情境片段.mp4':'课程开场配图.png';document.querySelector('.bui-file-tile').innerHTML=icon(kind);document.querySelector('#editButton').hidden=true;document.querySelector('#regionButton').hidden=kind!=='image';document.querySelector('#archiveButton').disabled=false;document.querySelector('#saveStatus').textContent='已保存';studioSelectedOutput=kind;refreshStudioShelf();if(kind==='image')renderImageRegionNotes()};
  const showStudioVisualAsset=showAsset;
  showAsset=function(kind){if(kind!=='audio')return showStudioVisualAsset(kind);if(!currentStudioSession().hasOutputs)return toast('当前会话暂无媒体成果');if(dirty)return toast('请先保存 Markdown 草稿，再切换成果');editing=false;const r=resources[6],p=document.querySelector('#paper');p.dataset.asset='audio';p.innerHTML=`<div class="eyebrow">AUDIO · 课程成果</div><h1>沟通练习示范音频</h1><p class="doc-sub">客户沟通基础课 · 口播节奏参考</p><div class="large-art studio-media-art">${art(r)}</div><div class="row between" style="margin-top:20px"><span class="pill">口播节奏参考</span><span class="tiny">音频素材</span></div>`;document.querySelector('.doc-name strong').textContent='沟通练习示范音频.mp3';document.querySelector('.bui-file-tile').innerHTML=icon('audio');document.querySelector('#editButton').hidden=true;document.querySelector('#regionButton').hidden=true;document.querySelector('#archiveButton').disabled=false;document.querySelector('#saveStatus').textContent='已保存';studioSelectedOutput='audio';refreshStudioShelf()};
  toggleEdit=function(){if(!currentStudioSession().hasOutputs)return;if(editing){if(!saveDocument())return;editing=false;document.querySelector('#paper').innerHTML=paperContent();document.querySelector('#editButton').innerHTML=icon('edit')+'编辑'}else{if(document.querySelector('#paper').dataset.asset)return;editing=true;document.querySelector('#paper').innerHTML=`<textarea class="md-editor" id="markdownEditor" aria-label="Markdown 内容编辑">${esc(md)}</textarea>`;document.querySelector('#markdownEditor').addEventListener('input',()=>{dirty=true;document.querySelector('#saveStatus').textContent='未保存'});document.querySelector('#editButton').innerHTML=icon('check')+'保存';document.querySelector('#markdownEditor').focus()}};
  saveDocument=function(){if(!currentStudioSession().hasOutputs){toast('当前会话暂无可保存的文档');return false}return originalSaveDocument()};
 archiveDoc=function(){if(!currentStudioSession().hasOutputs)return;const kind=document.querySelector('#paper').dataset.asset;if(kind)return toast('已将'+canvasOutputLabel()+'保存到本项目资源库');originalArchiveDoc()};
  outputPicker=function(){if(!currentStudioSession().hasOutputs){openModal('当前会话成果','<div class="empty">暂无成果</div>');return}openModal('当前会话成果',`<div class="stack">${[['doc','客户沟通基础课.md'],['image','课程开场配图'],['audio','沟通练习示范音频'],['video','沟通情境片段']].map(([type,name])=>`<button class="row" onclick="closeModal();selectStudioOutput('${type}')">${icon(type)}${name}</button>`).join('')}</div>`)};

  sendMessage=function(){const message=document.querySelector('#message').value.trim();if(!message)return toast('请先输入协作需求');const citation=canvasCitation,attached=[...localAttachments],resourceRefs=[...studioResourceRefs],requestModel=selectedModel;const session=currentStudioSession();activeModelRuns.set(session.id,(activeModelRuns.get(session.id)||0)+1);session.status='进行中';modelBusy=true;refreshModelPicker();updateStudioExecutionState();if(session.hasOutputs){originalSendMessage()}else{document.querySelector('#message').value='';document.querySelector('#chatLog').insertAdjacentHTML('beforeend',`<div class="human" style="margin-top:24px">${esc(message)}</div><div class="ai-name">${icon('spark')}内容协作智能体</div><p class="ai-copy">已收到“${esc(message)}”。已开始处理“${esc(session.name)}”中的协作需求。</p><span class="pill">处理反馈</span>`);document.querySelector('#chatLog').scrollTop=document.querySelector('#chatLog').scrollHeight}const human=[...document.querySelectorAll('#chatLog .human')].at(-1);if(citation){human?.insertAdjacentHTML('afterbegin',`<span class="canvas-citation">${icon(citation.kind)}${esc(citation.label)}${citation.rect?` · 区域 ${citation.index}`:''}</span>`);canvasCitation=null;document.querySelector('#canvasCitationDraft')?.remove()}if(resourceRefs.length){human?.insertAdjacentHTML('afterbegin',resourceRefs.map(id=>{const r=resources.find(x=>x.id===id);return r?`<span class="canvas-citation">${icon(r.kind)}${esc(r.name)}</span>`:''}).join(''));studioResourceRefs=[];renderStudioResourceRefs()}if(attached.length){human?.insertAdjacentHTML('afterbegin',attached.map(file=>`<span class="canvas-citation">${icon(file.kind)}${esc(file.name)}${file.saved?' · 已选入库':''}</span>`).join(''));localAttachments=[];renderLocalAttachments()}human?.insertAdjacentHTML('beforeend',`<small class="message-model">模型：${esc(requestModel)}</small>`);appendBeautifulRun(session.id);setTimeout(()=>{const remaining=Math.max(0,(activeModelRuns.get(session.id)||1)-1);activeModelRuns.set(session.id,remaining);if(!remaining){session.status='已完成';settleBeautifulRun(session.id)}if(studioSessionId===session.id){modelBusy=remaining>0;refreshModelPicker()}updateStudioExecutionState()},850)};

 skillModal=function(){if(!currentStudioSession().hasOutputs)return toast('当前会话尚无已实践的共创经验可供总结');beautifulSkillApproval()};
 referenceResource=function(id,stay=false){if(!resources.some(r=>r.id===id))return;if(!studioResourceRefs.includes(id))studioResourceRefs.push(id);if(document.querySelector('#modal').open)closeModal();renderStudioResourceRefs();toast('资源已加入当前会话')};
  const startingAsset=qs.get('asset');studioSelectedOutput=['image','audio','video'].includes(startingAsset)?startingAsset:'doc';refreshStudioShelf();document.querySelector('#documentPane').dataset.sessionId=studioSessionId;beautifySelectedReference();if(['image','audio','video'].includes(startingAsset))showAsset(startingAsset);captureStudioSession();const requestedSession=qs.get('session');if(studioSessions.some(t=>t.id===requestedSession)&&requestedSession!==studioSessionId)switchStudioSession(requestedSession);updateStudioExecutionState();
}

function updateStudioExecutionState(){const list=document.querySelector('#studioSessionList');if(list)list.innerHTML=studioSessionRows(document.querySelector('#sessionSearch').value);const status=document.querySelector('.chat-panel .panel-head > .tiny');if(status)status.textContent=currentStudioSession().status||''}
function canvasOutputLabel(){return document.querySelector('.doc-name strong')?.textContent||'当前成果'}
