function regionNotesKey(){return 'image-regions-'+studioSessionId+'-2'}
function regionNotes(){return read(regionNotesKey(),[])}
function startImageRegion(){const image=document.querySelector('#regionImage');if(!image)return;image.classList.add('selecting');image.onpointerdown=regionPointerDown;image.onpointermove=regionPointerMove;image.onpointerup=regionPointerUp;document.querySelector('#regionButton').classList.add('active');toast('在图片上拖动，框选需要讨论的区域')}
function regionPosition(e,image){const b=image.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))}}
function drawRegionRect(rect,el){Object.assign(el.style,{left:(rect.x*100)+'%',top:(rect.y*100)+'%',width:(rect.w*100)+'%',height:(rect.h*100)+'%'})}
function regionPointerDown(e){if(e.button!==0)return;const image=e.currentTarget;regionStart=regionPosition(e,image);regionRect=null;image.setPointerCapture(e.pointerId);const draft=document.querySelector('#regionDraft');draft.hidden=false;drawRegionRect({x:regionStart.x,y:regionStart.y,w:0,h:0},draft);e.preventDefault()}
function regionPointerMove(e){if(!regionStart)return;const p=regionPosition(e,e.currentTarget);regionRect={x:Math.min(regionStart.x,p.x),y:Math.min(regionStart.y,p.y),w:Math.abs(p.x-regionStart.x),h:Math.abs(p.y-regionStart.y)};drawRegionRect(regionRect,document.querySelector('#regionDraft'))}
function regionPointerUp(e){if(!regionStart)return;regionPointerMove(e);regionStart=null;const image=e.currentTarget;image.classList.remove('selecting');image.onpointerdown=null;image.onpointermove=null;image.onpointerup=null;document.querySelector('#regionButton').classList.remove('active');if(!regionRect||regionRect.w<.025||regionRect.h<.025){cancelImageRegion();toast('选区过小，请重新框选');return}const notes=regionNotes(),panel=document.querySelector('#regionNotePanel');panel.hidden=false;document.querySelector('#regionNumber').textContent=notes.length+1;document.querySelector('#regionCoordinates').textContent=`${Math.round(regionRect.w*100)}% × ${Math.round(regionRect.h*100)}%`;panel.scrollIntoView({block:'nearest',behavior:'smooth'});document.querySelector('#regionNoteText').focus()}
function cancelImageRegion(){regionStart=null;regionRect=null;const draft=document.querySelector('#regionDraft');if(draft)draft.hidden=true;const panel=document.querySelector('#regionNotePanel');if(panel)panel.hidden=true;const image=document.querySelector('#regionImage');if(image){image.classList.remove('selecting');image.onpointerdown=null;image.onpointermove=null;image.onpointerup=null}document.querySelector('#regionButton')?.classList.remove('active')}
function addImageRegionNote(){const content=document.querySelector('#regionNoteText').value.trim();if(!content)return toast('请输入提问或备注');if(!regionRect)return toast('请先框选图片区域');const type=document.querySelector('input[name="regionNoteType"]:checked').value,notes=regionNotes(),note={index:notes.length+1,type,text:content,rect:regionRect,imageId:2,imageVersion:'demo-1'};notes.push(note);write(regionNotesKey(),notes);renderImageRegionNotes();setCanvasCitation({kind:'image',label:'课程开场配图.png',rect:note.rect,index:note.index});document.querySelector('#message').value=content;cancelImageRegion();sendMessage();toast(`区域 ${note.index} 已引用到会话，可继续框选`)}
function renderImageRegionNotes(){const image=document.querySelector('#regionImage');if(!image)return;const notes=regionNotes();document.querySelector('#regionMarks').innerHTML=notes.map(note=>`<button class="region-mark" style="left:${note.rect.x*100}%;top:${note.rect.y*100}%;width:${note.rect.w*100}%;height:${note.rect.h*100}%" title="区域 ${note.index}：${esc(note.text)}" aria-label="区域 ${note.index}，${esc(note.type)}：${esc(note.text)}" onpointerdown="event.stopPropagation()" onclick="showImageRegionNote(${note.index})"><span>${note.index}</span></button>`).join('');document.querySelector('#regionNoteList').innerHTML=notes.length?`<strong>已引用的局部内容 · ${notes.length}</strong>`+notes.map(note=>`<button onclick="showImageRegionNote(${note.index})"><span>${note.index}</span><b>${esc(note.type)}</b>${esc(note.text)}</button>`).join(''):''}
function showImageRegionNote(index){const note=regionNotes().find(n=>n.index===index);if(!note)return;setCanvasCitation({kind:'image',label:'课程开场配图.png',rect:note.rect,index:note.index});document.querySelector('#message').focus();toast(`区域 ${index} 已加入会话输入区`)}
