function beautifulReferences(){stagedResourceIds=new Set(studioResourceRefs);activeReferenceType='文档';referenceCategoryChecks=Object.fromEntries(referenceTypes.map(type=>[type,new Set()]));referenceExpandedCategories=Object.fromEntries(referenceTypes.map(type=>[type,new Set(resourceCategoryPaths(type).filter(path=>!path.includes(' / ')))]));referenceQueries=Object.fromEntries(referenceTypes.map(type=>[type,'']));openModal('选择资源',`<div class="bui-resource-type-tabs" id="resourceTypeTabs" role="tablist" aria-label="资源类型">${renderReferenceTypeTabs()}</div><div class="bui-resource-layout"><aside class="bui-category-pane"><div class="bui-category-heading"><strong>资源分类</strong><button class="bui-category-clear" id="clearResourceCategories" onclick="clearReferenceCategories()">清除筛选</button></div><div id="resourceCategoryTree">${renderResourceCategoryTree()}</div></aside><div class="bui-resource-pane"><div class="bui-reference-search">${icon('search')}<input id="referenceSearch" aria-label="搜索资源" placeholder="搜索资源名称" oninput="filterBeautifulReferences()"></div><div class="bui-resource-result-head"><strong id="resourceResultTitle">全部分类</strong><span id="resourceResultCount"></span></div><div class="bui-search-list" id="referenceResults">${beautifulReferenceRows()}</div></div></div><div class="bui-modal-caption">${icon('lock')}仅显示当前项目可访问的资源</div>`,`<span class="bui-selected-count" id="referenceSelectedCount">已选择 ${stagedResourceIds.size} 项</span><button onclick="closeModal()">取消</button><button class="primary" id="confirmReferences" onclick="confirmResourceSelection()">确认引用</button>`);document.querySelector('#modal').classList.add('bui-resource-modal');updateReferenceResults()}
