function localFileType(file){const ext=file.name.split('.').pop().toLowerCase();if(['md','txt','pdf','doc','docx','ppt','pptx','xls','xlsx'].includes(ext))return ['文档','doc'];if(['png','jpg','jpeg','webp','gif'].includes(ext))return ['图片','image'];if(['mp3','wav','m4a','aac'].includes(ext))return ['音频','audio'];if(['mp4','mov','webm'].includes(ext))return ['视频','video'];return ['待确认','doc']}
